/**
 * The contract both `input.tsx` (native) and `input.web.tsx` implement.
 *
 * It lives in its own module because Metro resolves `./input` to `input.web.tsx`
 * on web — the web file importing the shared pieces from `./input` would be
 * importing itself.
 */

import type { Ref } from "react";

/**
 * Everything but `text`, `number`, `password` and the four keyboard types falls back to plain text
 * entry off web.
 *
 * `password` is here because it is the one non-web type native implements properly:
 * `secureTextEntry` masks the field and tells the platform keyboard to leave it out of
 * autocorrect and the suggestion strip. `email`, `search`, `url` and `tel` raise the matching
 * keyboard on device — they are `inputMode`s there and real input types on web. `time`,
 * `datetime-local`, `date` and `color` are real DOM controls with no native counterpart, and
 * degrade to a text box.
 *
 * The web half takes every DOM input type on top of these (`input.web.tsx`), so a shadcn call site
 * with `type="checkbox"` or `type="file"` still compiles there; this list is the part that means
 * something on both platforms.
 */
export type InputType =
  | "text"
  | "number"
  | "password"
  | "email"
  | "search"
  | "url"
  | "tel"
  | "time"
  | "date"
  | "datetime-local"
  | "color";

/** The keyboard each type raises on native when the caller has not chosen one with `inputMode`. */
export const NATIVE_INPUT_MODE: Partial<Record<InputType, NonNullable<InputProps["inputMode"]>>> = {
  number: "numeric",
  email: "email",
  search: "search",
  url: "url",
  tel: "tel",
};

/**
 * What a caller may do to an input imperatively. `select` is web-only —
 * `TextInput` has no equivalent — so callers must treat it as optional.
 *
 * On web the ref is the `<input>` itself rather than an object built to this shape: an
 * `HTMLInputElement` already has both methods, so a `Ref<InputHandle>` is served by it, and a
 * shadcn call site holding a `useRef<HTMLInputElement>` gets the element it asked for.
 */
export type InputHandle = {
  focus: () => void;
  select?: () => void;
};

/**
 * What `onKeyPress` hands over: the key, as `nativeEvent.key`. React Native's
 * `TextInputKeyPressEvent` is this shape, and so is a React DOM keyboard event, whose
 * `nativeEvent` is the browser's `KeyboardEvent` — so one handler reads the key the same way on
 * both halves. Spelled structurally because this file ships to the web too, where there is no
 * react-native to import the type from.
 */
export type InputKeyPressEvent = { nativeEvent: { key: string } };

/**
 * A handler of that event, declared as a method so its parameter is checked bivariantly — the
 * trick React's own event handler types use. A native handler annotated
 * `(e: TextInputKeyPressEvent) => void` names a narrower event than this one and would otherwise
 * be refused, though it reads nothing that is not here.
 */
export type InputKeyPressHandler = {
  bivarianceHack(event: InputKeyPressEvent): void;
}["bivarianceHack"];

export type InputProps = {
  value?: string | undefined;
  /** Uncontrolled: where the text starts, when nothing above is holding `value`. */
  defaultValue?: string | undefined;
  onChangeText?: ((text: string) => void) | undefined;
  onBlur?: (() => void) | undefined;
  /** Enter on web, the return key on native. */
  onSubmitEditing?: (() => void) | undefined;
  /**
   * Every key as it goes down: React Native's `onKeyPress`. On device that is a hardware keyboard
   * and whatever the soft one reports; on the web half it fires from `keydown`, as
   * react-native-web's does, so it hears Escape and the arrows, which a DOM `keypress` never does.
   */
  onKeyPress?: InputKeyPressHandler | undefined;
  /**
   * Escape — the key an inline edit answers with "put it back the way it was". Fires after any
   * `onKeyPress`, on both halves. A soft keyboard has no Escape key, so a touch-only screen still
   * needs its own way out (a blur, a cancel button).
   */
  onEscape?: (() => void) | undefined;
  placeholder?: string | undefined;
  type?: InputType | undefined;
  /**
   * Which keyboard to raise. Not the same knob as `type`: `type="number"` is what
   * gets the DOM spinners and the browser's numeric parsing, `inputMode="decimal"`
   * is what gets a phone keypad, and a number field wants both.
   */
  inputMode?: "text" | "decimal" | "numeric" | "tel" | "search" | "email" | "url" | undefined;
  maxLength?: number | undefined;
  /** Web only; the native keyboard has no equivalent constraint. */
  min?: number | undefined;
  max?: number | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
  /**
   * Ties the control to its `<label>` on the web. React Native takes `id` as its `nativeID`, so on
   * device it is only a target for another element's `aria-labelledby`.
   */
  id?: string | undefined;
  /**
   * The accessible name, for an input no `<label>` points at — the time box beside
   * a date trigger. `TextInput` takes it on device, and react-native-web renders it.
   */
  "aria-label"?: string | undefined;
  /**
   * The accessible name by reference. The web honours a list of ids; Android reads one, and iOS
   * none, so a native caller that needs the name everywhere passes `aria-label` too.
   */
  "aria-labelledby"?: string | undefined;
  autoFocus?: boolean | undefined;
  ref?: Ref<InputHandle> | undefined;
};

export const INPUT_CLASS =
  "border-input bg-background text-foreground ring-offset-background placeholder:text-muted-foreground focus-visible:ring-ring flex h-10 w-full rounded-md border px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2";

/**
 * The native implementation. `input.web.tsx` is its web counterpart, and
 * `input-base.ts` holds the contract they share.
 *
 * This is the plainest primitive that genuinely needs the split:
 * `type="time"` and `type="number"` (with `min`/`max`) are real DOM input
 * behaviour that `TextInput` cannot reproduce, and react-native-web offers no
 * way to reach them. Because both files export the
 * same `InputProps`, call sites never branch — the only rules are that they
 * speak `onChangeText` rather than `onChange`, and reach the element through
 * `InputHandle` rather than an `HTMLInputElement` ref. (The web half takes both
 * of those as well, as shadcn's `Input` does; shared code should not.)
 */

import { useImperativeHandle, useRef } from "react";
import { TextInput } from "react-native";
import {
  INPUT_CLASS,
  type InputHandle,
  type InputKeyPressEvent,
  type InputKeyPressHandler,
  type InputProps,
  type InputType,
  NATIVE_INPUT_MODE,
} from "@/components/ui/input-base";
import { cn } from "@/lib/utils";

function Input({
  className,
  type = "text",
  inputMode,
  value,
  defaultValue,
  onChangeText,
  onBlur,
  onSubmitEditing,
  onKeyPress,
  onEscape,
  placeholder,
  maxLength,
  disabled,
  autoFocus,
  id,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ref,
}: InputProps) {
  const inner = useRef<TextInput>(null);
  useImperativeHandle<InputHandle, InputHandle>(ref, () => ({
    focus: () => inner.current?.focus(),
  }));

  return (
    <TextInput
      ref={inner}
      value={value}
      defaultValue={defaultValue}
      onChangeText={onChangeText}
      onBlur={onBlur}
      onSubmitEditing={onSubmitEditing}
      onKeyPress={(event: InputKeyPressEvent) => {
        onKeyPress?.(event);
        if (event.nativeEvent.key === "Escape") onEscape?.();
      }}
      placeholder={placeholder}
      maxLength={maxLength}
      editable={!disabled}
      autoFocus={autoFocus}
      id={id}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledBy}
      inputMode={inputMode ?? NATIVE_INPUT_MODE[type] ?? "text"}
      secureTextEntry={type === "password"}
      className={cn(INPUT_CLASS, disabled && "opacity-50", className)}
    />
  );
}

export type { InputHandle, InputKeyPressEvent, InputKeyPressHandler, InputProps, InputType };
export { Input };

/**
 * The web implementation — see `input.tsx` for why this one is split, and
 * `input-base.ts` for the contract both sides implement.
 *
 * It keeps the DOM `<input>` so `type="time"`, `type="number"` and `min`/`max`
 * keep working, and adapts the event to the shared `onChangeText` contract so
 * no call site has to know which platform it is on.
 *
 * **It is also shadcn's `Input`, prop for prop.** This file installs at the
 * same `components/ui/input.tsx` a DOM app's shadcn primitive lives at, so the
 * first `shadcn add @cubeui/…` overwrites that primitive — and every
 * `<Input onChange={(e) => …}>`, `name`, `defaultValue`, `onKeyDown`, every DOM
 * input `type` and every `useRef<HTMLInputElement>` already in the app has to
 * keep compiling and keep working. So the props are the shared contract on top
 * of `ComponentProps<"input">`, both change handlers fire, and the ref is the
 * element (which already satisfies `InputHandle`, so shared call sites holding
 * one are served by the same object).
 */

import type {
  ComponentPropsWithoutRef,
  HTMLInputTypeAttribute,
  KeyboardEventHandler,
  Ref,
} from "react";
import {
  INPUT_CLASS,
  type InputHandle,
  type InputKeyPressEvent,
  type InputKeyPressHandler,
  type InputType,
  type InputProps as SharedInputProps,
} from "@/components/ui/input-base";
import { cn } from "@/lib/utils";

/**
 * The shared contract, widened to everything a DOM `<input>` takes.
 *
 * `onBlur`, `min`/`max`, `value` and `defaultValue` take the DOM's wider types — a `() => void` is
 * still one, and a `string` is still a `string | number | readonly string[]` — and `type` is every
 * DOM input type, of which `InputType` is the cross-platform part. `onKeyPress` hands over the
 * React keyboard event, which is a shared handler's `{ nativeEvent: { key } }` and a shadcn call
 * site's `e.key` at once.
 */
export type InputProps = Omit<
  ComponentPropsWithoutRef<"input">,
  "type" | "className" | "onKeyPress"
> &
  Omit<
    SharedInputProps,
    | "type"
    | "ref"
    | "onBlur"
    | "min"
    | "max"
    | "inputMode"
    | "value"
    | "defaultValue"
    | "onKeyPress"
  > & {
    type?: HTMLInputTypeAttribute | undefined;
    ref?: Ref<HTMLInputElement> | Ref<InputHandle> | undefined;
    onKeyPress?: KeyboardEventHandler<HTMLInputElement> | undefined;
  };

function Input({
  className,
  type = "text",
  onChange,
  onChangeText,
  onKeyDown,
  onKeyPress,
  onSubmitEditing,
  onEscape,
  ref,
  ...props
}: InputProps) {
  return (
    <input
      // The element is the handle: it has `focus` and `select`, which is all `InputHandle` asks.
      ref={ref as Ref<HTMLInputElement>}
      data-slot="input"
      type={type}
      onChange={(e) => {
        onChange?.(e);
        onChangeText?.(e.target.value);
      }}
      onKeyDown={(e) => {
        onKeyDown?.(e);
        // `keydown`, not the DOM's `keypress`: that one is deprecated and never fires for Escape,
        // the key `onKeyPress` is most often passed to hear. react-native-web makes the same swap.
        onKeyPress?.(e);
        if (e.defaultPrevented) return;
        if (e.key === "Enter" && onSubmitEditing) {
          e.preventDefault();
          onSubmitEditing();
        } else if (e.key === "Escape" && onEscape) {
          // Held back from the browser, which would otherwise clear a `type="search"` box under
          // a caller that is putting the old value back.
          e.preventDefault();
          onEscape();
        }
      }}
      {...props}
      className={cn(
        INPUT_CLASS,
        "file:border-0 file:bg-transparent file:text-sm file:font-medium disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive",
        className,
      )}
    />
  );
}

export type { InputHandle, InputKeyPressEvent, InputKeyPressHandler, InputType };
export { Input };
